import React from 'react';
import {
    HashRouter as Router,
    Switch,
    Route,
    // Link
} from 'react-router-dom';
//pages;
import PagesHome from './Home/Home';
import PagesLogin from './Admin/Login';
import PagesPainel from './Admin/Painel';
import BannersHome from './Banners/BannersHome';
import BannersTop from './Banners/BannersTop';
import BannersContent from './Banners/BannersContent';


const Root = () => {
    return (
        <Router>
            <Switch>
                <Route path="/BannersConteudo" component={BannersContent} /> 
                <Route path="/BannersTopo" component={BannersTop} />       
                <Route path="/Banners" component={BannersHome} />
                <Route path="/painel" component={PagesPainel} />
                <Route path="/admin" component={PagesLogin} />
                <Route path="/" component={PagesHome} />
            </Switch>
        </Router>
    )
}

export default Root;