import './Login.scss'
import Logo from '../../images/logo.png'
// import {
//     Link
// } from 'react-router-dom';
import firebase from '../../firebase'
import React, { Component } from 'react';
import ModalAlert from '../../components/ModalAlert/ModalAlert';
import $ from 'jquery';

class PagesLogin extends Component {

    modalAlert(text){
        $('.modalAlert').addClass('show').find('.modalAlert__modal__content').html(text);
        $('.closeModal').click(function(){
            $('.modalAlert').removeClass('show').find('.modalAlert__modal__content').html('');
        });
    }

    toggleSignIn() {
        let self = this;
        
        if (firebase.auth().currentUser) {
        // [START signout]
        firebase.auth().signOut();
        // [END signout]
        } else {
        var email = document.getElementById('emailUser').value;
        var password = document.getElementById('passwordUser').value;
        if (email.length < 4) {
            alert('Digite um endereço de email valido!');
            return;
        }
        if (password.length < 4) {
            self.modalAlert('Digite uma senha!');
            return;
        }
        // Sign in with email and pass.
        // [START authwithemail]
        firebase.auth().signInWithEmailAndPassword(email, password).catch(function(error) {
            // Handle Errors here.
            var errorCode = error.code;
            var errorMessage = error.message;
            // [START_EXCLUDE]
            if (errorCode === 'auth/wrong-password') {
            alert('Senha incorreta!.');
            } else {
            alert(errorMessage);
            }
            console.log(error);
            document.getElementById('quickstart-sign-in').disabled = false;
            // [END_EXCLUDE]
        });
        // [END authwithemail]
        }
        document.getElementById('quickstart-sign-in').disabled = true;
    }


    initApp() {
        firebase.auth().onAuthStateChanged(function(user) {
          if (user) {
            // User is signed in.
            let displayName = user.displayName,
                email = user.email,
                emailVerified = user.emailVerified,
                //photoURL = user.photoURL,
                //isAnonymous = user.isAnonymous,
                uid = user.uid,
                providerData = user.providerData;
    
            let userData = {
                'displayName': displayName,
                'email': email,
                'emailVerified': emailVerified,
                'providerData': providerData,
                'uid':uid
            }
            
            sessionStorage.setItem('userData', JSON.stringify(userData));
    
            window.location = '/#/painel';
            // if (!emailVerified) {
            //   document.getElementById('quickstart-verify-email').disabled = false;
            // }
            // 
          } 
        });
        //document.getElementById('quickstart-sign-in').addEventListener('click', toggleSignIn, false);
        // document.getElementById('quickstart-sign-up').addEventListener('click', handleSignUp, false);
        // document.getElementById('quickstart-verify-email').addEventListener('click', sendEmailVerification, false);
        // document.getElementById('quickstart-password-reset').addEventListener('click', sendPasswordReset, false);
    }

    
    sendPasswordReset() {
        var email = document.getElementById('emailUser').value;
        // [START sendpasswordemail]
        firebase.auth().sendPasswordResetEmail(email).then(function() {
        // Password Reset Email Sent!
        // [START_EXCLUDE]
        alert('Email de recuperação de senha enviado!');
        // [END_EXCLUDE]
        }).catch(function(error) {
        // Handle Errors here.
        var errorCode = error.code;
        var errorMessage = error.message;
        // [START_EXCLUDE]
        if (errorCode === 'auth/invalid-email') {
            alert(errorMessage);
        } else if (errorCode === 'auth/user-not-found') {
            alert(errorMessage);
        }
        console.log(error);
        // [END_EXCLUDE]
        });
        // [END sendpasswordemail];
    }

    componentDidMount(){
        this.initApp();
    }   

    render() {
        return(
            <>
            <ModalAlert />
            <section className="loginSection">

                <div className="loginSection__logo">
                    <img src={Logo} alt="Logomarca" />
                </div>

                <div className="loginSection__area">
                    <h2>Área de Login</h2>
                    <input id="emailUser" type="email" placeholder="E-mail" /> 
                    <input id="passwordUser" type="password" placeholder="Senha" />
                    <button id="quickstart-sign-in" className="button button--primary" onClick={this.toggleSignIn}>Acessar</button>
                    {/* <Link to="#" id="quickstart-password-reset" onClick={this.sendPasswordReset} className="button button--link">Esqueci minha senha</Link> */}
                </div>

            </section>
            </>
        )
    }
}

export default PagesLogin;