import './Banner.scss'
import React from 'react';
import {
    Link
} from 'react-router-dom';

const Banner = ({imgDesk, imgMobile, text, link}) => {
    return(
        <>
        <section className="banner">
            <Link to={link}><img className="banner__desk" src={imgDesk} alt={text} /></Link>
            <Link to={link}><img className="banner__mobile" src={imgMobile} alt={text} /></Link>
        </section>
        </>
    )
}

export default Banner;