import './NavLeft.scss'
import {
    Link
} from 'react-router-dom';
//import firebase from '../../firebase'
import React, { Component } from 'react';
import $ from 'jquery';

class NavLeft extends Component {

    navSubOpen(){
        $('.adminNav__group__item span').click(function(){
            var verifyClass = $(this).parents('.adminNav__group__item ').hasClass('active');
            if ( verifyClass !== true) {
                $(this).parents('.adminNav__group__item ').addClass('active');
                $(this).parents('.adminNav__group__item ').find('.adminNav__group__item__sub').addClass('active');
                $(this).parents('.adminNav__group__item ').find('.special-icon').removeClass('icon-plus').addClass('icon-minus');
            } else {
                $(this).parents('.adminNav__group__item ').removeClass('active');
                $(this).parents('.adminNav__group__item ').find('.adminNav__group__item__sub').removeClass('active');
                $(this).parents('.adminNav__group__item ').find('.special-icon').addClass('icon-plus').removeClass('icon-minus');
            }
        });
    }

    navMobile() {
        $('.headerAdmin__navMobile').click(function(){
            var verifyClass = $(this).hasClass('opened');
            if(verifyClass !== true) {
                $(this).addClass('opened');
                $(this).find('i').removeClass('icon-menu').addClass('icon-cross');
                $('.colum-left').addClass('opened');
            } else {
                $(this).removeClass('opened');
                $(this).find('i').addClass('icon-menu').removeClass('icon-cross');
                $('.colum-left').removeClass('opened');  
            }   
        });
    }
    
    navPin(item, sub){
        item.addClass('active');
        item.find('.adminNav__group__item__sub').addClass('active');
        item.find('.special-icon').removeClass('icon-plus').addClass('icon-minus');
        if(sub !== undefined && sub !== null) {
           $(`.${sub}`).addClass('active');
        }
    }

    verifyNav(){
        let self= this,
            getHash = window.location.hash;
        //verifica e executa o menu de banners    
        if(getHash === '#/Banners'){
            let item = $('.adminNav__group__item.pagebanner');
            self.navPin(item);
        }
        if(getHash === '#/BannersTopo'){
            let item = $('.adminNav__group__item.pagebanner'),
                sub = getHash.toLocaleLowerCase().replace('/','');
            self.navPin(item, sub);
        }
        if(getHash === '#/BannersConteudo'){
            let item = $('.adminNav__group__item.pagebanner'),
                sub = getHash.toLocaleLowerCase().replace('/','');
            self.navPin(item, sub);
        }

        
    }

    componentDidMount(){
        this.navSubOpen();
        this.navMobile();
        this.verifyNav();
    }  

    render() {
        return(
            <>
            <nav className="adminNav">
                <ul className="adminNav__group">
                    <li className="adminNav__group__item">
                        <Link to="/painel"><span><i className="icon-home"></i>Inicio</span></Link>
                    </li>

                    {/* <li className="adminNav__group__item">
                        <Link to="/Banners"><span><i className="icon-image"></i>Banners</span></Link>
                    </li> */}

                    <li className="adminNav__group__item pagebanner">
                        <span><i className="icon-image"></i>Banners <i className="icon-plus special-icon"></i></span>
                        <ul className="adminNav__group__item__sub">
                            <li className="adminNav__group__item__sub__list">
                                <Link to="/BannersTopo" className="bannerstopo">Banners Topo</Link>
                            </li>
                            <li className="adminNav__group__item__sub__list">
                                <Link to="/BannersConteudo" className="bannersconteudo">Banners do conteúdo</Link>
                            </li>
                        </ul>
                    </li>

                    {/* <li className="adminNav__group__item">
                        <span><i className="icon-image"></i>Banners Disponibilidade <i className="icon-plus special-icon"></i></span>
                        <ul className="adminNav__group__item__sub">
                            <li className="adminNav__group__item__sub__list">
                                <Link to="/CadastrarBannersDisponibilidade">Cadastrar um banner</Link>
                            </li>
                            <li className="adminNav__group__item__sub__list">
                                <Link to="/BannersDisponibilidadeCadastrados">Banners cadastrados</Link>
                            </li>
                        </ul>
                    </li> */}

                </ul>
            </nav>
            </>
        )
    }
}

export default NavLeft;