import './ModalConfirm.scss'
import React, { Component } from 'react';

class ModalConfirm extends Component {
    render() {
        return(
            <>
                <div className="modalConfirm">
                    <div className="modalConfirm__overlay"></div>
                    <div className="modalConfirm__modal">
                        <div className="modalConfirm__modal__content">
                            <span className="modalConfirm__modal__content__text">Deseja mesmo deletar este item?</span>
                            <button className="modalConfirm__modal__content__button modalConfirm__modal__content__button--confirm btRemove">Deletar</button>
                            <button className="modalConfirm__modal__content__button modalConfirm__modal__content__button--cancel btCancel">Cancelar</button>
                        </div>
                    </div>
                </div>
            </>
        )
    }
}

export default ModalConfirm;