import './HeaderAdmin.scss'
import Logo from '../../images/logo.png'
import {
    Link
} from 'react-router-dom';
import firebase from '../../firebase'
import React, { Component } from 'react';
import $ from 'jquery';

class HeaderAdmin extends Component {

    LogOut(){
        if (firebase.auth().currentUser) {
            firebase.auth().signOut();
        }
    }
    
    userNotLogged(){
        firebase.auth().onAuthStateChanged(function(user) {
            if (user) {
              let userEmail = firebase.auth().currentUser.email,
                  userInitial = userEmail.split('')[0];
              $('.headerAdmin__userInfos__logout span').html(userEmail);
              $('.headerAdmin__userInfos__initials span').html(userInitial);
              
            } else {
                window.location = '/#/admin';
            }
        });
    }

    componentDidMount(){
        this.userNotLogged();
    }   

    render() {
        return(
            <>
            <header className="headerAdmin">
                <div className="container-fluid">
                    <div className="row">
                        <div className="col-xs-7">
                            <button className="headerAdmin__navMobile"><i className="icon-menu"></i></button>
                            <Link to="/painel"><img src={Logo} alt="Logomarca" className="headerAdmin__logo" /></Link>
                        </div>
                        <div className="col-xs-5">
                            <ul className="headerAdmin__userInfos">
                                <li className="headerAdmin__userInfos__home">
                                    <span></span>
                                    <Link to="/painel"><i className="icon-home"></i></Link>
                                </li>
                                <li className="headerAdmin__userInfos__logout">
                                    <span></span>
                                    <Link to="#" id="logOut" onClick={this.LogOut}><i className="icon-switch"></i>Sair</Link>
                                </li>
                                <li className="headerAdmin__userInfos__initials">
                                    <span></span>
                                </li>
                            </ul>
                        </div>
                    </div>
                </div>
            </header>
            </>
        )
    }
}

export default HeaderAdmin;