//import firebase from '../../firebase'
import './Banners.scss'
import firebase from '../../firebase'
import React, { Component } from 'react';
import NavLeft from '../../components/NavLeft/NavLeft';
import HeaderAdmin from '../../components/HeaderAdmin/HeaderAdmin';
import ModalAlert from '../../components/ModalAlert/ModalAlert';
import ModalConfirm from '../../components/ModalConfirm/ModalConfirm';
import Loader from '../../components/Loader/Loader';
import $ from 'jquery';


class BannersTop extends Component {

    modalAlert(text){
        $('.modalAlert').addClass('show').find('.modalAlert__modal__content').html(text);
        $('.closeModal').click(function(){
            $('.modalAlert').removeClass('show').find('.modalAlert__modal__content').html('');
        });
    }

    inserLoader() {
        $('.loader').addClass('show')
    }
    removeLoader() {
        $('.loader').removeClass('show')
    }

    sendRegisterBannerCarrosel(){
        let self  = this;
        $('#imageBanner').change(function(event){
            self.inserLoader();
            let firstFile = event.target.files[0] // upload the first file only
            let nameImage = event.target.files[0].name;
            firebase.storage().ref(`banners/carrosel/${nameImage}`).put(firstFile).then(snapshot => snapshot.ref.getDownloadURL())
            .then((url) => {
                $('#imageArea').html(`<img src="${url}">`);
                self.removeLoader();
                alert('imagem carregada!');
            })
            .catch(console.error);
        });

        $('#sendRegisterBannerCarrosel').click(function(){
            let titleBanner = $('#titleBanner').val().trim(),
                imageBanner = $('#imageArea img').attr('src'),
                linkBanner = $('#linkBanner').val().trim(),
                bannerType = $('input[name="bannerType"]:checked').attr('data-value'),
                bannerTypeVal = '',
                positionBanner = $('#positionBanner').val();
            
            //verifgica se titulo tem valor
            if(titleBanner === null || titleBanner === undefined || titleBanner === '') {
                self.modalAlert('Titulo do banner é obrigatório!');
                return false;
            } 

            //valida se tem a imagem
            if(imageBanner === '' || imageBanner === undefined || imageBanner === null){
                self.modalAlert('imagem obrigatória');
                return false;
            }

            if(bannerType !== null && bannerType !== undefined){
                bannerTypeVal = bannerType;
            }
            //se posição não esta marcada não deixa avançar
            if(bannerTypeVal === ''){
                self.modalAlert('o tipo de Banner é obrigatório!');
                return false;
            }

            //verifgica se banner tem valor diferente de zero e acima de zero
            if(positionBanner === null || positionBanner === undefined || positionBanner === '' || positionBanner === '0') {
                self.modalAlert('Posição do banner deve ser maior que zero!');
                return false;
            } 

            let obj = {
                'title': titleBanner,
                'image': imageBanner,
                'linkBanner': linkBanner,
                'bannerType': bannerType,
                'position': positionBanner
            };
            
            $('#imageArea').html('');
            self.registerBannerCarrosel(obj);
        });
    }

    registerBannerCarrosel(obj){
        
        let self = this;
        firebase.database().ref().child('bannerCarrosel').push({
            obj
        }, function(error) {
            if (error) {
                self.removeLoader();
                self.modalAlert('Falha ao cadastrar Banner!');
                console.log(error);
            } else {
                self.removeLoader();
                self.modalAlert('Sucecsso ao cadastrar Banner');
                $('.bannerRegister input').val('');   
            }
        });
    }

    //pega os banners
    getBannersList(){
        let self = this;
        firebase.database().ref('bannerCarrosel').on('value', function(snapshot){
            let htmlInsertDesk = '',
                htmlInsertMobile = '';
            snapshot.forEach(function(item){
                let key = item.key,
                    data = item.val().obj,
                    title = data.title,
                    image = data.image,
                    linkBanner = data.linkBanner,
                    bannerType = data.bannerType,
                    position = data.position;

                if(bannerType === 'desktop'){
                    htmlInsertDesk += `<div class="col-md-12">`;
                    htmlInsertDesk += `<div class="bannerRegistred__content__item">`;
                    htmlInsertDesk += `<div class="row">`;
                    htmlInsertDesk += `<div class="col-xs-12">`;
                    htmlInsertDesk += `<h3>${title}</h3>`;
                    htmlInsertDesk += `<div class="bannerRegistred__content__item__contentImg"><img src="${image}" /></div>`;
                    htmlInsertDesk += ` </div>`;
                    htmlInsertDesk += `<div class="col-xs-8">`;
                    htmlInsertDesk += `Posição do banner: ${position} <br />`;
                    htmlInsertDesk += `Tipo de banner: ${bannerType}  <br />`;
                    htmlInsertDesk += `Link do banner: ${linkBanner}`;
                    htmlInsertDesk += `</div>`;
                    htmlInsertDesk += `<div class="col-xs-4">`;
                    htmlInsertDesk += `<button class="bannerRegistred__content__item__button  bannerRegistred__content__item__button--delete btDelete" data-key="${key}">`;
                    htmlInsertDesk += `<i class="icon-cross"></i> Apagar`;
                    htmlInsertDesk += `</button>`;
                    htmlInsertDesk += `</div>`;
                    htmlInsertDesk += `</div>`;
                    htmlInsertDesk += `</div>`;
                    htmlInsertDesk += `</div>`;
                }
                if(bannerType === 'mobile'){
                    htmlInsertMobile += `<div class="col-md-12">`;
                    htmlInsertMobile += `<div class="bannerRegistred__content__item">`;
                    htmlInsertMobile += `<div class="row">`;
                    htmlInsertMobile += `<div class="col-xs-12">`;
                    htmlInsertMobile += `<h3>${title}</h3>`;
                    htmlInsertMobile += `<div class="bannerRegistred__content__item__contentImg"><img src="${image}" /></div>`;
                    htmlInsertMobile += ` </div>`;
                    htmlInsertMobile += `<div class="col-xs-8">`;
                    htmlInsertMobile += `Posição do banner: ${position} <br />`;
                    htmlInsertMobile += `Tipo de banner: ${bannerType}  <br />`;
                    htmlInsertMobile += `Link do banner: ${linkBanner}`;
                    htmlInsertMobile += `</div>`;
                    htmlInsertMobile += `<div class="col-xs-4">`;
                    htmlInsertMobile += `<button class="bannerRegistred__content__item__button  bannerRegistred__content__item__button--delete btDelete" data-key="${key}">`;
                    htmlInsertMobile += `<i class="icon-cross"></i> Apagar`;
                    htmlInsertMobile += `</button>`;
                    htmlInsertMobile += `</div>`;
                    htmlInsertMobile += `</div>`;
                    htmlInsertMobile += `</div>`;
                    htmlInsertMobile += `</div>`;
                }

                
            });
            $('.bannerRegistred__content.desktop').html(htmlInsertDesk);
            $('.bannerRegistred__content.mobile').html(htmlInsertMobile);
            self.removeBannerCarrosel();
        });
    }

    removeBannerCarrosel(){
        $('.btDelete').click(function(){
            let key = $(this).attr('data-key');
            
            $('.modalConfirm').addClass('show');
            $('.btCancel').click(function(){
                $('.modalConfirm').removeClass('show');
            });
            $('.btRemove').click(function(){
                $('.modalConfirm').removeClass('show');
                firebase.database().ref('bannerCarrosel').child(key).remove();
            });
            
        });
    }
 

    componentDidMount(){
        this.sendRegisterBannerCarrosel();
        this.getBannersList();
    }   


    render() {
        return(
            <>
            <HeaderAdmin />
            <ModalAlert />
            <ModalConfirm />
            <Loader />

            <div className="colum-left">
                <NavLeft />
            </div>

            <div className="colum-right">
                <section className="bannerRegister">
                    <div className="container-fluid">
                        <div className="row">
                            <div className="col-md-7">
                                <h2 className="formTitle">Cadastrar Banners no Carrosel</h2>
                                <div className="contentBox form">

                                    <div className="form__group">
                                        <label>Titulo do banner</label>
                                        <input type="text" id="titleBanner" placeholder="Digite um titulo para o seu banner" />
                                    </div>

                                    <div className="form__group">
                                        <label>*Imagem do Banner</label>
                                        <div className="row">
                                            <div className="col-xs-12">
                                                <div className="form__group__imagearea" id="imageArea"></div>
                                            </div>
                                            <div className="col-xs-12">
                                                <input type="file" accept="image/*" capture="camera" id="imageBanner" />
                                            </div>
                                        </div>                            
                                    </div>
                                    
                                    <div className="form__group">
                                        <label>Link do banner</label>
                                        <input type="text" id="linkBanner" placeholder="Exemplo: https://www.exemplo.com.br" />
                                    </div>

                                    <div className="form__group">
                                        <label>Medida do banner: Desktop ou Celular</label>
                                        <ul className="form__group__options" id="bannerType">
                                            <li className="form__group__options__list">
                                                <input type="radio" data-value="desktop" name="bannerType" />
                                                <span>Desktop</span>
                                            </li>
                                            <li className="form__group__options__list">
                                                <input type="radio" data-value="mobile" name="bannerType" />
                                                <span>Celular</span>
                                            </li>
                                        </ul>
                                    </div>

                                    <div className="form__group">
                                        <label>Posição do banner</label>
                                        <input type="number" id="positionBanner" placeholder="Digite o número da posição do banner" />
                                    </div>

                                </div>
                                <button id="sendRegisterBannerCarrosel" className="button button--primary button--right">Cadastrar</button>

                            </div>

                            <div className="col-md-5">
                                <section className="bannerRegistred">
                                    <div className="container-fluid">
                                        <div className="row">
                                            <div className="col-md-12">
                                                <h2 className="formTitle">Banners Cadastrados Desktop</h2>
                                                <div className="contentBox">
                                                    <div className="bannerRegistred__content desktop row"></div>
                                                </div>

                                                <h2 className="formTitle">Banners Cadastrados Celular</h2>
                                                <div className="contentBox">
                                                    <div className="bannerRegistred__content mobile row"></div>
                                                </div>
                                            </div>    
                                        </div>
                                    </div>
                                </section>
                            </div> 
                        </div>
                    </div>
                </section>
            </div>
            </>
        )
    }
}

export default BannersTop;