import './ModalAlert.scss'
import React, { Component } from 'react';

class ModalAlert extends Component {
    render() {
        return(
            <>
                <div className="modalAlert">
                    <div className="modalAlert__overlay"></div>
                    <div className="modalAlert__modal">
                        <div className="modalAlert__modal__button"><i className="closeModal icon-cross"></i></div>
                        <div className="modalAlert__modal__content"></div>
                    </div>
                </div>
            </>
        )
    }
}

export default ModalAlert;